import{_ as e,o as d,c as o,ae as r}from"./chunks/framework.Dh1jimFm.js";const b=JSON.parse('{"title":"Keyboard Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"editor/keyboard-shortcuts.md","filePath":"editor/keyboard-shortcuts.md"}'),a={name:"editor/keyboard-shortcuts.md"};function i(l,t,n,c,s,h){return d(),o("div",null,t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>Master these shortcuts to work faster in Supervertaler.</p><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>↑/↓</code></td><td>Previous/next segment when cursor is at the first/last line of the cell</td></tr><tr><td><code>Alt+Up</code></td><td>Previous segment (always)</td></tr><tr><td><code>Alt+Down</code></td><td>Next segment (always)</td></tr><tr><td><code>Ctrl+G</code></td><td>Go to segment number</td></tr><tr><td><code>Page Up</code></td><td>Previous page (pagination)</td></tr><tr><td><code>Page Down</code></td><td>Next page (pagination)</td></tr><tr><td><code>Ctrl+Home</code></td><td>First segment</td></tr><tr><td><code>Ctrl+End</code></td><td>Last segment</td></tr></tbody></table><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Enter</code></td><td>Confirm current (or selected) segment(s)</td></tr><tr><td><code>Ctrl+Shift+Enter</code></td><td>Confirm selected segments</td></tr><tr><td><code>Ctrl+Z</code></td><td>Undo</td></tr><tr><td><code>Ctrl+Y</code></td><td>Redo</td></tr><tr><td><code>Ctrl+C</code></td><td>Copy</td></tr><tr><td><code>Ctrl+V</code></td><td>Paste</td></tr><tr><td><code>Ctrl+X</code></td><td>Cut</td></tr><tr><td><code>Ctrl+A</code></td><td>Select all (in cell)</td></tr><tr><td><code>Shift+Enter</code></td><td>Insert line break inside a cell</td></tr><tr><td><code>Ctrl+,</code></td><td>Insert next tag / wrap selection with a tag pair (when available)</td></tr></tbody></table><h2 id="translation" tabindex="-1">Translation <a class="header-anchor" href="#translation" aria-label="Permalink to &quot;Translation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+T</code></td><td>Translate current segment with AI</td></tr><tr><td><code>Ctrl+Shift+T</code></td><td>Translate multiple segments</td></tr><tr><td><code>Ctrl+1…9</code></td><td>Insert match #1…#9</td></tr><tr><td><code>Ctrl+Space</code></td><td>Insert currently selected match</td></tr><tr><td><code>Ctrl+Up</code></td><td>Previous match (results panel)</td></tr><tr><td><code>Ctrl+Down</code></td><td>Next match (results panel)</td></tr></tbody></table><h2 id="find-replace" tabindex="-1">Find &amp; Replace <a class="header-anchor" href="#find-replace" aria-label="Permalink to &quot;Find &amp; Replace&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+F</code></td><td>Open Find &amp; Replace dialog</td></tr><tr><td><code>F3</code></td><td>Find next</td></tr><tr><td><code>Shift+F3</code></td><td>Find previous</td></tr><tr><td><code>Ctrl+H</code></td><td>Replace (same as Ctrl+F)</td></tr></tbody></table><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Shift+F</code></td><td>Filter on selected text (toggle)</td></tr></tbody></table><h2 id="lookup" tabindex="-1">Lookup <a class="header-anchor" href="#lookup" aria-label="Permalink to &quot;Lookup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+K</code></td><td>Open Superlookup</td></tr><tr><td><code>Ctrl+Alt+L</code></td><td>System-wide TM lookup (if configured)</td></tr></tbody></table><h2 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Plus</code></td><td>Increase font size</td></tr><tr><td><code>Ctrl+Minus</code></td><td>Decrease font size</td></tr></tbody></table><h2 id="file-operations" tabindex="-1">File Operations <a class="header-anchor" href="#file-operations" aria-label="Permalink to &quot;File Operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+S</code></td><td>Save project</td></tr><tr><td><code>Ctrl+O</code></td><td>Open project</td></tr><tr><td><code>Ctrl+N</code></td><td>New project</td></tr></tbody></table><h2 id="voice-commands-if-enabled" tabindex="-1">Voice Commands (if enabled) <a class="header-anchor" href="#voice-commands-if-enabled" aria-label="Permalink to &quot;Voice Commands (if enabled)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>F9</code></td><td>Push-to-talk / Stop always-on listening</td></tr></tbody></table><hr><h2 id="customizing-shortcuts" tabindex="-1">Customizing Shortcuts <a class="header-anchor" href="#customizing-shortcuts" aria-label="Permalink to &quot;Customizing Shortcuts&quot;">​</a></h2><p>You can view and customize shortcuts in <strong>Settings → Keyboard Shortcuts</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Some shortcuts match memoQ conventions (like <code>Ctrl+Enter</code> to confirm) to help translators who switch between tools.</p></div><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><h3 id="memoq-style-navigation" tabindex="-1">memoQ-Style Navigation <a class="header-anchor" href="#memoq-style-navigation" aria-label="Permalink to &quot;memoQ-Style Navigation&quot;">​</a></h3><p>The arrow keys work like memoQ:</p><ul><li>Press <code>↓</code> at the <strong>last line</strong> of a cell to move to the next segment</li><li>Press <code>↑</code> at the <strong>first line</strong> of a cell to move to the previous segment</li><li>Cursor column position is preserved when moving between segments</li></ul><h3 id="quick-filtering" tabindex="-1">Quick Filtering <a class="header-anchor" href="#quick-filtering" aria-label="Permalink to &quot;Quick Filtering&quot;">​</a></h3><ol><li>Select text in any segment</li><li>Press <code>Ctrl+Shift+F</code> to filter</li><li>Only segments containing that text are shown</li><li>Press <code>Ctrl+Shift+F</code> again to clear filter</li></ol>',30)]))}const m=e(a,[["render",i]]);export{b as __pageData,m as default};
